const items = $input.all();

// Fallback order by known document IDs (prior hardcoded fetches).
const ID_ORDER = {
  'YOUR_DOCUMENT_ID': 0,
  'YOUR_DOCUMENT_ID': 1,
  'YOUR_DOCUMENT_ID': 2,
  'YOUR_DOCUMENT_ID': 3,
  'YOUR_DOCUMENT_ID': 4,
  'YOUR_DOCUMENT_ID': 5,
  'YOUR_DOCUMENT_ID': 6,
  'YOUR_DOCUMENT_ID': 7,
  'YOUR_DOCUMENT_ID': 8,
  'YOUR_DOCUMENT_ID': 9,
  'YOUR_DOCUMENT_ID': 10,
};

function rankByName(name) {
  const n = (name || '').toLowerCase();
  if (/neurophysiology/.test(n)) return 0;
  if (/ens|gastroenterology|gastro/.test(n)) return 2;
  if (/psychology/.test(n)) return 3;
  if (/identity/.test(n)) return 4;
  if (/social/.test(n) && !/protocol/.test(n)) return 5;
  if (/sleep protocol/.test(n)) return 6;
  if (/sleep/.test(n)) return 1;
  if (/exercise/.test(n)) return 7;
  if (/skin/.test(n)) return 8;
  if (/balanced/.test(n)) return 9;
  if (/low-carbohydrate/.test(n)) return 10;
  return 99;
}

function rank(documentId, name) {
  if (ID_ORDER[documentId] !== undefined) return ID_ORDER[documentId];
  return rankByName(name);
}

const sorted = items
  .map((item) => ({
    documentId: item.json.documentId || item.json.id,
    content: item.json.content ?? '',
    name: item.json.name || '',
  }))
  .sort((a, b) => rank(a.documentId, a.name) - rank(b.documentId, b.name));

return sorted.map(({ documentId, content }) => ({
  json: { documentId, content },
}));

const items = $input.all();

// 1. Extract Life History
// Filter for items that specifically have a 'documentId'
const lifeHistory = items
  .filter(item => item.json.documentId)
  .map(item => item.json.content)
  .join('\n\n');

// 2. Extract Conversation History
// Filter for items that specifically represent an AI agent message
const conversation_history = items
  .filter(item => item.json.agent_name)
  .map(item => {
    let msgBlock = `[${item.json.agent_name} - Iteration ${item.json.iteration}]: ${item.json.content}`;

    // Append fact-checker feedback if it exists from previous iterations
    if (item.json.fact_check_feedback) {
      msgBlock += `\n\n[Epistemologist Fact-Check on ${item.json.agent_name}]:\n${item.json.fact_check_feedback}`;
    }

    return msgBlock;
  })
  .join('\n\n--------------------------------------------------\n\n');

// 3. Extract Session Variables
// Find the single item in the array that contains the session data
const sessionData = items.find(item => item.json.current_session_id)?.json || {};

// 4. Return the unified payload
return [{
  json: {
    lifeHistory: lifeHistory,
    session_id: sessionData.current_session_id,
    max_loops: sessionData.max_loops,
    conversation_history: conversation_history
  }
}];
